use std::fs
use std::env

fn emit(text: string, number: bool, counter: int) -> int {
    let mut c = counter
    if number {
        for line in text.lines() {
            c += 1
            println("${c:>6}\t${line}")
        }
    } else {
        print("${text}")
    }
    c
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
        } else if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let t = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(t, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f.clone()) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    std::process::exit(status)
}

